def _diff_booleans(self, level, local_tree=None):
    """Diff booleans"""
    # If we reach this point, it means we're dealing with boolean values
    # or values that are being treated as booleans due to ignore_type_in_groups
    if level.t1 != level.t2:
        self._report_result('values_changed', level, local_tree=local_tree)
